{"consulta": "WITH importes AS (
  SELECT cliente_id, SUM(cantidad * precio_unitario * (1 - descuento)) AS importe
  FROM ventas
  WHERE fecha >= '2025-01-01' AND fecha <= '2025-12-31'
  GROUP BY cliente_id
),
tot AS (
  SELECT SUM(importe) AS total_2025 FROM importes
),
top10 AS (
  SELECT SUM(importe) AS importe_top10 FROM (
    SELECT importe FROM importes ORDER BY importe DESC LIMIT 10
  )
)
SELECT t.total_2025, d.importe_top10, ROUND(100.0 * d.importe_top10 / t.total_2025, 2) AS porcentaje
FROM tot t, top10 d"}
